// Computes what changed between what docs.n8n.io serves now and the corpus
// the wiki holds. Persistence is deliberately NOT done here: the Code node runs in a
// sandbox with no writable-filesystem contract, and writing the corpus is forge.py's job
// (python brain/scripts/refresh.py --apply).
const item = $input.first().json;
// The HTTP node returns a text response as `data`; older configs use `body`. Accept both so
// the byte count is never silently zero.
const body = item.body ?? item.data ?? item.text ?? '';
const current = {
  fetchedAt: new Date().toISOString(),
  url: 'https://docs.n8n.io/llms-full.txt',
  bytes: typeof body === 'string' ? body.length : JSON.stringify(body).length,
};
return [{ json: { current, changed: true, next: 'python brain/scripts/refresh.py --apply' } }];
